package test;
import com.winlator.sysvshm.*;import com.winlator.renderer.*;import com.winlator.xserver.*;import com.winlator.xserver.extensions.*;import com.winlator.xserver.errors.*;import com.winlator.xconnector.*;import java.nio.*;import java.lang.reflect.*;
public class ResourceRegression {
 static void expect(boolean b,String msg){if(!b)throw new AssertionError(msg);}
 static GPUImage cpuImport(int fd)throws Exception{try{return GPUImage.class.getConstructor(int.class,boolean.class).newInstance(fd,true);}catch(NoSuchMethodException e){return new GPUImage(fd);}}
 static void fdImport(XClient c,int id,int fd)throws Throwable{call("pixmapFromFd",new Class[]{XClient.class,int.class,short.class,short.class,int.class,int.class,byte.class,int.class,long.class},c,id,(short)32,(short)16,128,0,(byte)24,fd,2048L);}
 static void hardwareImport(XClient c,int id,int fd)throws Throwable{call("pixmapFromHardwareBuffer",new Class[]{XClient.class,int.class,short.class,short.class,byte.class,int.class},c,id,(short)32,(short)16,(byte)24,fd);}
 static void call(String n,Class<?>[] types,Object... args)throws Throwable{var m=DRI3Extension.class.getDeclaredMethod(n,types);m.setAccessible(true);try{m.invoke(new DRI3Extension(),args);}catch(InvocationTargetException e){throw e.getCause();}}
 static XInputStream request(boolean buffers,int window,int fd,long mod){var i=new XInputStream();i.fd=fd;i.b=ByteBuffer.allocate(80);i.b.putInt(7).putInt(window);if(!buffers){i.b.putInt(2048).putShort((short)32).putShort((short)16).putShort((short)128).put((byte)24).put((byte)32);}else{i.b.putInt(1).putShort((short)32).putShort((short)16).putInt(128).putInt(0).put(new byte[24]).put((byte)24).put(new byte[3]).putLong(mod);}i.b.flip();return i;}
 public static void main(String[] args)throws Throwable{int c=Integer.parseInt(args[0]);Drawable.DRAWABLE_ASR_MODE(true);
 switch(c){
 case 0:{var s=new SysVSharedMemory();int id=s.get(2048);var a=s.attach(id);var b=s.attach(id);expect(a==b,"fixture mapping sharing");s.detach(a);expect(Hooks.maps.contains(b),"detaching one alias unmapped another active client");s.detach(b);expect(Hooks.maps.isEmpty(),"last alias must unmap");break;}
 case 1:{var s=new SysVSharedMemory();int id=s.get(2048);var a=s.attach(id);s.delete(id);expect(Hooks.maps.contains(a),"IPC delete must not invalidate current attachment");s.detach(a);expect(Hooks.maps.isEmpty(),"delete removed mapping ownership before detach; mapping leaked");break;}
 case 2:{var s=new SysVSharedMemory();int id=s.get(2048);var manager=new SHMSegmentManager(s);manager.attach(7,id);var a=manager.getData(7);s.deleteAll();expect(Hooks.maps.contains(a),"deleteAll invalidates running X readers");manager.detach(7);expect(Hooks.maps.isEmpty(),"session teardown left native mappings live");expect(Hooks.fds.isEmpty(),"session teardown left FDs live");break;}
 case 3:{Hooks.ashmemFails=true;var s=new SysVSharedMemory();int id=s.get(2048);int fd=s.getFd(id);Hooks.shared.close();expect(Hooks.fds.contains(fd),"returned FD is borrowed from SharedMemory and closes with its wrapper");expect(s.attach(id)!=null,"owned FD must remain usable");s.detach(s.attach(id));break;}
 case 4:{var x=new XClient();int fd=Hooks.fd();fdImport(x,7,fd);expect(Hooks.creates==0,"DRI3 imported memory allocated throwaway hardware buffers: "+Hooks.creates);expect(Hooks.buffers.isEmpty(),"DRI3 import leaked displaced hardware buffers: "+Hooks.buffers.size());x.xServer.pixmapManager.freePixmap(7);expect(Hooks.maps.isEmpty(),"pixmap free must unmap");break;}
 case 5:{var x=new XClient();hardwareImport(x,7,Hooks.fd());var d=x.xServer.pixmapManager.getPixmap(7).drawable;expect(d.width==32,"hardware pixmap used uninitialized CPU stride as width: "+d.width);expect(d.height==16,"height preserved");break;}
 case 6:{var x=new XClient();int fd=Hooks.fd();var i=request(false,99,fd,0);x.data=2;try{new DRI3Extension().handleRequest(x,i,new XOutputStream());throw new AssertionError("invalid window accepted");}catch(BadWindow e){}expect(!Hooks.fds.contains(fd)&&i.fd==-1,"rejected import left FD queued for following request");break;}
 case 7:{var x=new XClient();int fd=Hooks.fd();var i=request(true,1,fd,999);x.data=7;try{new DRI3Extension().handleRequest(x,i,new XOutputStream());throw new AssertionError("unknown modifier silently accepted without pixmap/error");}catch(BadImplementation e){}expect(!Hooks.fds.contains(fd),"unsupported modifier leaked FD");break;}
 case 8:{Hooks.receiveFails=true;var x=new XClient();int fd=Hooks.fd();try{hardwareImport(x,7,fd);throw new AssertionError("failed hardware import registered an empty pixmap");}catch(BadAlloc e){}expect(x.xServer.pixmapManager.getPixmap(7)==null,"failed import left installed pixmap");expect(!Hooks.fds.contains(fd),"failed import FD not closed");break;}
 case 9:{var image=new AHBImage((short)32,(short)16);image.destroy();int fd=Hooks.fd();image.setSwapchainFence(1,fd);expect(!Hooks.fds.contains(fd),"late SurfaceControl release callback stored FD after destroy");break;}
 case 10:{Hooks.eglFails=true;var image=new GPUImage((short)32,(short)16);image.allocateTexture((short)32,(short)16,null);expect(image.getHardwareBufferPtr()==0,"failed EGL must release AHB");expect(image.getVirtualData()==null,"failed EGL leaves CPU pointer to freed AHB");expect(!image.isAllocated(),"failed EGL retains unusable GL texture");break;}
 case 11:{Drawable.DRAWABLE_ASR_MODE(false);var d=new Drawable(1,32,16,new Visual());var t=d.getTexture();t.updateFromDrawable(d);t.updateFromDrawable(d);expect(Hooks.uploads==1,"unchanged frame uploaded twice after allocation: "+Hooks.uploads);d.forceUpdate();t.updateFromDrawable(d);expect(Hooks.uploads==2,"changed frame must upload");break;}

 case 12:{var s=new SysVSharedMemory();int id=s.get(2048);expect(s.getFd(id)>=0,"allocation FD");var a=s.attach(id);expect(a!=null,"valid mapping");s.detach(a);expect(Hooks.maps.isEmpty(),"single mapping cleanup");s.delete(id);expect(Hooks.fds.isEmpty(),"single FD cleanup");break;}
 case 13:{var x=new XClient();int fd=Hooks.fd();fdImport(x,7,fd);expect(!Hooks.fds.contains(fd),"successful FD import closes transferred FD");expect(x.xServer.pixmapManager.getPixmap(7).drawable.getData()!=null,"successful FD import installs bytes");break;}
 case 14:{var a=new AHBImage((short)32,(short)16);int f=Hooks.fd(),g=Hooks.fd();a.setSwapchainFence(1,f);a.setSwapchainFence(1,g);expect(!Hooks.fds.contains(f)&&Hooks.fds.contains(g),"new fence replaces only previous fence");a.destroy();expect(Hooks.fds.isEmpty()&&Hooks.buffers.isEmpty(),"ordinary AHB destruction balances references");break;}
 case 15:{var image=new GPUImage((short)32,(short)16);image.allocateTexture((short)32,(short)16,null);expect(image.isAllocated()&&image.getVirtualData()!=null,"successful GPU allocation");image.destroy();expect(Hooks.buffers.isEmpty()&&image.getVirtualData()==null,"normal GPU destruction");expect(Hooks.glDeletes==1,"normal GL texture cleanup");break;}
 case 16:{Drawable.DRAWABLE_ASR_MODE(false);var d=new Drawable(1,32,16,new Visual());var t=d.getTexture();t.updateFromDrawable(d);int old=Hooks.uploads;d.forceUpdate();t.updateFromDrawable(d);expect(Hooks.uploads==old+1,"new pixel damage remains visible");break;}
 case 17:{var x=new XClient();int fd=Hooks.fd();var i=request(true,1,fd,1255);x.data=7;new DRI3Extension().handleRequest(x,i,new XOutputStream());expect(x.xServer.pixmapManager.getPixmap(7)!=null,"known hardware modifier imports");expect(!Hooks.fds.contains(fd),"known modifier closes FD");break;}
 case 18:{var x=new XClient();int fd=Hooks.fd();var i=request(true,1,fd,1274);x.data=7;new DRI3Extension().handleRequest(x,i,new XOutputStream());expect(x.xServer.pixmapManager.getPixmap(7).drawable.getData()!=null,"known CPU modifier imports");expect(!Hooks.fds.contains(fd),"known CPU modifier closes FD");break;}

 case 19:{var a=new AHBImage((short)32,(short)16);int[] fds=new int[1000];for(int i=0;i<fds.length;i++)fds[i]=Hooks.fd();var start=new java.util.concurrent.CountDownLatch(1);var worker=new Thread(()->{try{start.await();for(int i=0;i<fds.length;i++)a.setSwapchainFence(i%3,fds[i]);}catch(Exception e){throw new RuntimeException(e);}});worker.start();start.countDown();a.destroy();worker.join();expect(Hooks.fds.isEmpty(),"release callback/destroy race leaked FDs");expect(Hooks.buffers.isEmpty(),"destroy race leaked buffers");a.destroy();expect(Hooks.fds.isEmpty(),"repeated destroy must be harmless");break;}

 case 20:{var s=new SysVSharedMemory();int id=s.get(2048);var x=new XServer();x.shm=new SHMSegmentManager(s);x.shm.attach(1,id);s.deleteAll();var component=new com.winlator.xenvironment.components.XServerComponent(x,null);var field=component.getClass().getDeclaredField("connector");field.setAccessible(true);field.set(component,new XConnectorEpoll(null,null,null));Hooks.requireStopped=true;component.stop();expect(Hooks.connectorStopped,"dispatcher stop");expect(Hooks.maps.isEmpty(),"component stop failed to release remaining mappings");component.stop();break;}
 case 21:{var image=new GPUImage(Hooks.fd());expect(image.getHardwareBufferPtr()!=0,"DRI3 AHB import failed");expect(Hooks.locks==0,"Vulkan DRI3 import needlessly CPU-locks GPU-written AHB");image.destroy();expect(Hooks.buffers.isEmpty(),"imported AHB leaked");break;}
 case 22:{Hooks.lockFails=true;var image=new GPUImage(Hooks.fd());expect(image.getHardwareBufferPtr()!=0,"GPU-readable AHB was rejected solely because CPU locking is unsupported");image.destroy();expect(Hooks.buffers.isEmpty(),"failed CPU-lock control leaked AHB");break;}
 case 23:{var image=new GPUImage((short)32,(short)16);expect(Hooks.locks==1&&image.getVirtualData()!=null,"CPU-created window AHB must retain writable storage");image.destroy();expect(Hooks.unlocks==1,"CPU-created window AHB must be unlocked before release");break;}
 case 24:{var image=new GPUImage(Hooks.fd());image.destroy();expect(Hooks.unlocks==0,"imported GPU-only AHB must not receive CPU unlock");break;}
 case 25:{var image=cpuImport(Hooks.fd());expect(Hooks.locks==1&&image.getVirtualData()!=null,"GL imported pixmap still needs CPU-accessible storage");image.destroy();expect(Hooks.unlocks==1&&Hooks.buffers.isEmpty(),"GL imported AHB must unlock and release");break;}
 case 26:{Drawable.DRAWABLE_ASR_MODE(false);var x=new XClient();x.xServer.renderer=new com.winlator.renderer.VulkanRenderer();int fd=Hooks.fd();hardwareImport(x,7,fd);expect(Hooks.locks==0,"actual Vulkan DRI3 branch must not CPU-lock imported AHB");expect(x.xServer.pixmapManager.getPixmap(7)!=null&&!Hooks.fds.contains(fd),"Vulkan import installed and closes transferred FD");x.xServer.pixmapManager.freePixmap(7);expect(Hooks.buffers.isEmpty()&&Hooks.unlocks==0,"Vulkan imported AHB releases without CPU unlock");break;}
 case 27:{Drawable.DRAWABLE_ASR_MODE(false);var x=new XClient();hardwareImport(x,7,Hooks.fd());expect(Hooks.locks==1&&x.xServer.pixmapManager.getPixmap(7).drawable.getData()!=null,"non-Vulkan DRI3 branch retains CPU access");x.xServer.pixmapManager.freePixmap(7);expect(Hooks.buffers.isEmpty()&&Hooks.unlocks==1,"non-Vulkan import balances CPU lock");break;}
 }System.out.println("PASS case "+c);
 }
}
